<?php
$cfg=require __DIR__.'/../config.php';$secret=$cfg['payment']['secret_key'];$payload=file_get_contents('php://input');$signature=$_SERVER['HTTP_X_PAYSTACK_SIGNATURE']??'';if(!$secret||!hash_equals(hash_hmac('sha512',$payload,$secret),$signature)){http_response_code(401);exit('invalid signature');}$event=json_decode($payload,true);if(($event['event']??'')!=='charge.success'){http_response_code(200);exit('ignored');}require_once __DIR__.'/../db.php';$meta=$event['data']['metadata']??[];$uid=(int)($meta['user_id']??0);$plan=$meta['plan']??'';$ref=$event['data']['reference']??'';$amount=(int)($event['data']['amount']??0);if(!$uid||!$ref){http_response_code(422);exit('missing metadata');}try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT IGNORE INTO payments(user_id,provider,reference,plan,amount_kobo,status,paid_at) VALUES(?,?,?,?,?,\'paid\',?)');$q->execute([$uid,'paystack',$ref,$plan,$amount,date('Y-m-d H:i:s')]);if(str_starts_with($plan,'pro_')){$u=$pdo->prepare("UPDATE users SET plan='pro',updated_at=? WHERE id=?");$u->execute([date('Y-m-d H:i:s'),$uid]);}$pdo->commit();http_response_code(200);echo 'ok';}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo 'error';}
